const main = document.querySelector('#main');
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json = obj => esc(JSON.stringify(obj, null, 2));
let catalog = [];
async function api(path, body) {
  const response = await fetch('/v0/' + path, body === undefined ? {} : {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(body)});
  return {status:response.status, data:await response.json()};
}
function letter(subject, body, stamp='Library reply', from='fvapi library') {
  return `<article class="letter"><div class="address"><div><strong>From</strong> ${esc(from)}<br><strong>To</strong> ${from === 'You' ? 'fvapi library' : 'You'}<br><strong>File</strong> ${esc(subject)}</div><div class="stamp">${esc(stamp)}</div></div>${body}</article>`;
}
function status(recorded) { return `<span class="status ${recorded?'warning':''}">${recorded?'Recorded • not re-run by fvapi':'Replay available'}</span>`; }
function entryBody(e) {
  return `<h2>${esc(e.title)}</h2>${status(e.replay.status === 'recorded')}<p class="salutation">Dear caller,</p><p>${esc(e.claim)}</p><h3>The statement to inspect</h3>${e.statements.map(s=>`<p>${esc(s.name)}<br><small>${esc(s.file)}:${esc(s.line)}</small></p><pre>${esc(s.text)}</pre>`).join('')}<h3>Enclosures</h3><p>Compare every file with its SHA256 before you replay the proof.</p>${e.closure.map(f=>`<div class="enclosure"><strong>${esc(f.path)}</strong> <small>${esc(f.bytes)} bytes</small><code>SHA256 ${esc(f.sha256)}</code></div>`).join('')}<div class="actions"><a class="button" href="/v0/bundles/${encodeURIComponent(e.id)}.tar.gz">Download enclosures</a><a href="#check/${encodeURIComponent(e.id)}">Send input for a check</a></div><div class="postscript"><h3>P.S. Check this yourself</h3><p>${esc(e.replay.note)}</p>${e.replay.status === 'recorded'?'<p class="status warning">Recorded stub: not re-run by fvapi. This is not a fresh verification.</p>':''}<pre id="command">${esc(e.replay.command)}</pre><button class="secondary" id="copy">Copy replay command</button><dl><dt>Expected axioms</dt><dd>${esc(e.replay.expect_axioms.join(', '))}</dd><dt>Toolchain and dependencies</dt><dd>${esc(e.toolchain)}<br>${esc(e.requires.join(', '))}</dd><dt>Licence</dt><dd>${esc(e.licence.spdx)}</dd><dt>Third-party notices</dt><dd>${e.licence.third_party.length?e.licence.third_party.map(n=>`${esc(n.name)} / ${esc(n.spdx)} / ${esc(n.source)}`).join('<br>'):'No third-party notices listed.'}</dd><dt>Source</dt><dd>${esc(e.source.repo)}<br>Commit ${esc(e.source.commit)}<br>${e.source.paths.map(esc).join('<br>')}</dd></dl>${e.replay.transcript?`<details><summary>Recorded transcript</summary><pre>${esc(e.replay.transcript)}</pre></details>`:''}</div><p class="signature">Yours,<br>The fvapi library</p>`;
}
function bindCopy(){const b=document.querySelector('#copy'); if(b)b.onclick=async()=>{try{await navigator.clipboard.writeText(document.querySelector('#command').textContent);b.textContent='Replay command copied';}catch{b.textContent='Select the command above to copy it';}};}
async function showEntry(id) {
  const {status:code,data:e}=await api('catalog/'+encodeURIComponent(id));
  if(code!==200){const summary=catalog.find(x=>x.id===id);main.innerHTML=letter(id,`<h2>Entry file unavailable</h2>${summary?`<p>${esc(summary.claim)}</p>${status(summary.replay_status==='recorded')}`:''}<p>The API did not return the full entry. Choose another holding.</p>`);return;}
  main.innerHTML=letter(e.id,entryBody(e));bindCopy();
}
async function lookup(auto) {
  main.innerHTML=letter('Library enquiry',`<h2>Write to the library</h2><p>Dear library,</p><p>Please find a proof that matches this request.</p><form id="lookup"><label for="key">Match by</label><select id="key"><option value="spec_id">Specification ID</option><option value="artifact_sha256">Artifact SHA256</option><option value="statement">Statement text</option></select><label for="query">Request</label><input id="query" required value="${auto==='lookup-miss'?'unlisted.contrast':'vf.contrast-2x2'}"><button>Look up</button></form><p class="signature">Yours,<br>The caller</p>`, 'Outgoing', 'You')+'<div id="reply" class="thread"></div>';
  const form=document.querySelector('#lookup');form.onsubmit=async event=>{event.preventDefault();const {status:code,data:r}=await api('lookup',{[document.querySelector('#key').value]:document.querySelector('#query').value});const reply=document.querySelector('#reply');if(code===200){reply.innerHTML=letter(r.answer_id,`<h2>We found a matching entry.</h2><p>Dear caller,</p><p>The request matched ${esc(r.matched_on)}. The enclosures follow.</p>${entryBody(r.entry)}`);bindCopy();}else{reply.innerHTML=letter(r.miss_id || 'Enquiry reply',`<h2>${r.logged?'Your request is filed.':'The request could not be completed.'}</h2><p>Dear caller,</p><p>${esc(r.detail)}</p>${r.logged?'<p><strong>No match. Logged as demand.</strong> This does not start work on your request.</p><a href="#demand">Read the demand file</a>':'<p>Edit the request and try again.</p>'}`,'No match');}};
  if(auto)form.requestSubmit();
}
async function check(id='vf.contrast-2x2',auto) {
  const {data:e}=await api('catalog/'+encodeURIComponent(id));
  const example=e.check?.example_input || {};
  if(auto==='check-reject' && example.rows)example.rows[0].weights[0]=1;
  main.innerHTML=letter('Check request',`<h2>Send a check with an enclosure</h2><p>Dear library,</p><p>Please check the input below. Return the result and the instructions to repeat it.</p><form id="check"><label for="entry-id">Holding</label><select id="entry-id">${catalog.map(x=>`<option value="${esc(x.id)}" ${x.id===id?'selected':''}>${esc(x.id)}</option>`).join('')}</select><label for="input">Enclosed input (editable JSON)</label><textarea id="input" spellcheck="false">${json(example)}</textarea><p id="error" role="alert"></p><button>Run check</button></form>`,'Outgoing','You')+'<div id="reply" class="thread"></div>';
  document.querySelector('#entry-id').onchange=event=>{location.hash='check/'+event.target.value;};
  const form=document.querySelector('#check');form.onsubmit=async event=>{event.preventDefault();let input;try{input=JSON.parse(document.querySelector('#input').value);}catch{document.querySelector('#error').textContent='The input is not valid JSON. Correct it and run the check again.';return;}document.querySelector('#error').textContent='';const {status:code,data:r}=await api('checks/'+encodeURIComponent(document.querySelector('#entry-id').value),input);document.querySelector('#reply').innerHTML=letter(r.answer_id || 'Check reply',code===200?`<h2>Input ${esc(r.verdict === 'accept'?'accepted':'rejected')}.</h2><p>Dear caller,</p><p>The checker returned <strong>${esc(r.verdict)}</strong> on ${esc(r.ran_on)} in ${esc(r.elapsed_ms)} ms. Exit code: ${esc(r.exit_code)}.</p><pre>${json(r.output)}</pre><div class="enclosure"><strong>Submitted input SHA256</strong><code>${esc(r.input_sha256)}</code></div><div class="postscript"><h3>P.S. Repeat the check yourself</h3><pre>${esc(r.recheck.command)}</pre><a href="${esc(r.recheck.bundle)}">Download the bundle</a></div>`:`<h2>This holding has no checker.</h2><p>${esc(r.detail)}</p><p>Choose a checker holding and send your input again.</p><p class="status warning">HTTP ${code} / ${esc(r.error)}</p>`,code===200?'Check reply':'Cannot run');};
  if(auto)form.requestSubmit();
}
async function logs(kind){const {data:r}=await api(kind);main.innerHTML=letter(kind==='demand'?'Filed enquiries':'Reply register',`<h2>${kind==='demand'?'Requests without a match':'The reply register'}</h2><p>${kind==='demand'?'Unanswered enquiries stay on file. They do not start individual agent work.':'Lookups and checks, newest first. Open a holding to inspect its proof.'}</p>${kind==='demand'?`<h3>Filed demand by key</h3>${r.by_key.map(x=>`<div class="enclosure"><code>${esc(x.key)}</code><strong>${x.count} request${x.count===1?'':'s'}</strong></div>`).join('')}<h3>Correspondence file</h3>`:''}${(r.misses || r.answers).map(x=>`<div class="logrow"><strong>${esc(x.miss_id || x.answer_id)}</strong><br><small>${esc(x.at)}</small>${x.query?`<pre>${json(x.query)}</pre>`:`<p>${esc(x.kind)}${x.verdict?' / '+esc(x.verdict):''}</p><a href="#entry/${encodeURIComponent(x.entry_id)}">${esc(x.entry_id)}</a>`}</div>`).join('') || '<p>No letters on file. Write a request to begin.</p>'}`);}
async function route(){const [state='catalog',id]=location.hash.slice(1).split('/');document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+state)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});main.innerHTML='<p>Opening the correspondence…</p>';try{if(state==='entry')await showEntry(decodeURIComponent(id));else if(state==='recorded')await showEntry('fva.glm-iround');else if(state.startsWith('lookup'))await lookup(state==='lookup'?null:state);else if(state.startsWith('check'))await check(state==='check-409'?'fva.glm-iround':id?decodeURIComponent(id):'vf.contrast-2x2',state==='check'?null:state);else if(state==='demand'||state==='answers')await logs(state);else main.innerHTML=letter('Published holdings',`<h2>The library’s list of holdings</h2><p>Dear caller,</p><p>These are the claims available for enquiry. Each full entry includes its statement, proof files and instructions for an independent check.</p>${catalog.map(e=>`<section class="catalog-item"><div><small>${esc(e.kind)} / ${esc(e.id)}</small><h3><a href="#entry/${encodeURIComponent(e.id)}">${esc(e.title)}</a></h3><p>${esc(e.claim)}</p><small>${esc(e.licence_spdx)}</small></div>${status(e.replay_status==='recorded')}</section>`).join('')}<p class="signature">Yours,<br>The fvapi library</p>`,'Holdings');document.body.dataset.ready=state;}catch(error){main.innerHTML=letter('Service reply','<h2>The library could not be reached.</h2><p>Check the connection and reload this page.</p><pre>'+esc(error.message)+'</pre>','Connection error');}}
(async()=>{try{catalog=(await api('catalog')).data.entries;document.querySelector('#holdings').innerHTML=catalog.map(e=>`<a href="#entry/${encodeURIComponent(e.id)}">${esc(e.id)}<span>${e.replay_status==='recorded'?'Recorded • not re-run':'Checker / replay available'}</span></a>`).join('');window.addEventListener('hashchange',route);await route();}catch(error){main.textContent='The catalog could not be loaded. Check the connection and reload.';}})();
